package zoo

import (
	"context"
	"crypto/tls"
	"fmt"
	"net/http"
	"os/exec"
	"path/filepath"
	"testing"
	"time"

	"oxyp/internal/config"
	"oxyp/internal/daemon"
)

func insecureTransport() *http.Transport {
	return &http.Transport{TLSClientConfig: &tls.Config{InsecureSkipVerify: true}} //nolint:gosec // test probe only
}

func probeTransport(t *testing.T, mode string) *http.Transport {
	t.Helper()
	cfg := &tls.Config{InsecureSkipVerify: true} //nolint:gosec // test probe only
	if mode == "mtls" {
		// certs are generated by the zoo at startup; wait for them
		certs := filepath.Join(zooPath(t), "http", "certs")
		for range 50 {
			if cert, err := tls.LoadX509KeyPair(filepath.Join(certs, "client.crt"), filepath.Join(certs, "client.key")); err == nil {
				cfg.Certificates = []tls.Certificate{cert}
				break
			}
			time.Sleep(100 * time.Millisecond)
		}
	}
	return &http.Transport{TLSClientConfig: cfg}
}

func startZooTLS(t *testing.T, mode string, port int) {
	t.Helper()
	cmd := exec.Command("python3", filepath.Join(zooPath(t), "http", "zoo_tls.py"),
		"--mode", mode, "--port", fmt.Sprint(port))
	cmd.Stdout, cmd.Stderr = nil, nil
	if err := cmd.Start(); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = cmd.Process.Kill(); _ = cmd.Wait() })
	probe := &http.Client{Timeout: 500 * time.Millisecond,
		Transport: probeTransport(t, mode)}
	for range 100 {
		resp, err := probe.Get(fmt.Sprintf("https://127.0.0.1:%d/", port))
		if err == nil {
			resp.Body.Close()
			if resp.StatusCode == 200 {
				return
			}
		}
		time.Sleep(100 * time.Millisecond)
	}
	t.Fatalf("zoo-tls %s never listened on %d", mode, port)
}

func TestTLSZoo(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 90*time.Second)
	defer cancel()
	certs := filepath.Join(zooPath(t), "http", "certs")

	t.Run("self-signed-fails-by-default", func(t *testing.T) {
		port := freePort(t)
		startZooTLS(t, "self-signed", port)
		d := daemon.New(remoteCfg("t", fmt.Sprintf("https://127.0.0.1:%d/mcp", port), nil), testLog())
		defer d.Close()
		_, err := d.ListTools(ctx, "t")
		if err == nil {
			t.Fatal("want TLS verify failure, got success")
		}
		t.Logf("failed as expected: %v", err)
	})

	t.Run("custom-ca-succeeds", func(t *testing.T) {
		port := freePort(t)
		startZooTLS(t, "self-signed", port)
		cfg := &config.Config{Servers: map[string]config.ServerEntry{
			"t": {
				URL: fmt.Sprintf("https://127.0.0.1:%d/mcp", port),
				TLS: &config.TLSConfig{CAFile: filepath.Join(certs, "ca.crt")},
			},
		}}
		d := daemon.New(cfg, testLog())
		defer d.Close()
		tools, err := d.ListTools(ctx, "t")
		if err != nil || len(tools) != 1 {
			t.Fatalf("custom-ca list: tools=%d err=%v", len(tools), err)
		}
	})

	t.Run("insecure-succeeds", func(t *testing.T) {
		port := freePort(t)
		startZooTLS(t, "self-signed", port)
		cfg := &config.Config{Servers: map[string]config.ServerEntry{
			"t": {
				URL: fmt.Sprintf("https://127.0.0.1:%d/mcp", port),
				TLS: &config.TLSConfig{Insecure: true},
			},
		}}
		d := daemon.New(cfg, testLog())
		defer d.Close()
		tools, err := d.ListTools(ctx, "t")
		if err != nil || len(tools) != 1 {
			t.Fatalf("insecure list: tools=%d err=%v", len(tools), err)
		}
	})

	t.Run("mtls-required-without-cert-fails", func(t *testing.T) {
		port := freePort(t)
		startZooTLS(t, "mtls", port)
		cfg := &config.Config{Servers: map[string]config.ServerEntry{
			"t": {
				URL: fmt.Sprintf("https://127.0.0.1:%d/mcp", port),
				TLS: &config.TLSConfig{CAFile: filepath.Join(certs, "ca.crt")},
			},
		}}
		d := daemon.New(cfg, testLog())
		defer d.Close()
		_, err := d.ListTools(ctx, "t")
		if err == nil {
			t.Fatal("want mtls failure without client cert, got success")
		}
		t.Logf("failed as expected: %v", err)
	})

	t.Run("mtls-with-cert-succeeds", func(t *testing.T) {
		port := freePort(t)
		startZooTLS(t, "mtls", port)
		cfg := &config.Config{Servers: map[string]config.ServerEntry{
			"t": {
				URL: fmt.Sprintf("https://127.0.0.1:%d/mcp", port),
				TLS: &config.TLSConfig{
					CAFile:   filepath.Join(certs, "ca.crt"),
					CertFile: filepath.Join(certs, "client.crt"),
					KeyFile:  filepath.Join(certs, "client.key"),
				},
			},
		}}
		d := daemon.New(cfg, testLog())
		defer d.Close()
		tools, err := d.ListTools(ctx, "t")
		if err != nil || len(tools) != 1 {
			t.Fatalf("mtls list: tools=%d err=%v", len(tools), err)
		}
	})
}
